interface NavbarProps {
  currentPage: Page;
  setPage: (page: Page) => void;
}

const Navbar: React.FC<NavbarProps> = ({ currentPage, setPage }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 10);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks: { name: string; id: Page }[] = [
    { name: 'Início', id: 'home' },
    { name: 'O Que Fazemos', id: 'expertise' },
    { name: 'A Equipe', id: 'studio' },
    { name: 'Fale Conosco', id: 'contact' },
  ];

  const handleNav = (id: Page) => {
    setPage(id);
    setIsMobileMenuOpen(false);
    window.scrollTo(0, 0);
  };

  return (
    <nav 
      className={`fixed top-0 w-full z-50 transition-all duration-200 border-b ${
        scrolled || isMobileMenuOpen ? 'bg-black border-white/20' : 'bg-black/80 border-transparent backdrop-blur-sm'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
