             <div className="w-10 h-10 bg-white text-black flex items-center justify-center font-black font-display tracking-tighter text-xl">
                S
             </div>
             <div className="flex flex-col justify-center">
               <span className="font-display font-black text-3xl tracking-tighter text-white leading-none">STYH</span>
             </div>
          </div>

          {/* Desktop Nav */}
          <div className="hidden md:block">
            <div className="ml-10 flex items-center space-x-1">
              {navLinks.map((link) => (
                <button
                  key={link.id}
                  onClick={() => handleNav(link.id)}
                  className={`relative px-4 py-2 text-sm font-bold uppercase tracking-widest transition-colors hover:bg-white hover:text-black clip-path-slant ${
                    currentPage === link.id ? 'bg-white text-black' : 'text-gray-400'
                  }`}
                  style={{ clipPath: 'polygon(10% 0, 100% 0, 90% 100%, 0% 100%)' }}
                >
                  {link.name}
                </button>
              ))}

              <button 
                onClick={() => handleNav('contact')}
                className="ml-6 px-6 py-2 bg-brand-accent text-white font-bold font-display text-xs uppercase tracking-wider hover:bg-red-600 transition-colors"
              >
                Orçar Projeto
              </button>
            </div>
          </div>

          {/* Mobile Menu Button */}
          <div className="-mr-2 flex md:hidden">
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="inline-flex items-center justify-center p-2 rounded-md text-white hover:bg-white/10 focus:outline-none"
            >
              {isMobileMenuOpen ? <CloseIcon className="w-8 h-8" /> : <MenuIcon className="w-8 h-8" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      <div className={`md:hidden absolute top-20 left-0 w-full bg-black border-b border-white/10 transition-all duration-300 overflow-hidden ${isMobileMenuOpen ? 'max-h-screen opacity-100' : 'max-h-0 opacity-0'}`}>
        <div className="px-4 py-6 space-y-4 flex flex-col">
          {navLinks.map((link) => (
            <button
              key={link.id}
              onClick={() => handleNav(link.id)}
              className={`block w-full text-left px-4 py-4 text-2xl font-black uppercase tracking-tighter border-l-4 transition-all ${
                currentPage === link.id ? 'border-brand-accent text-white bg-white/5' : 'border-transparent text-gray-500 hover:text-white'
              }`}
            >
              {link.name}
            </button>
          ))}
          <button 
             onClick={() => handleNav('contact')}
             className="w-full py-5 bg-brand-accent text-white font-black uppercase tracking-widest mt-4"
          >
            Orçar Projeto Agora
          </button>
        </div>
      </div>
    </nav>
  );
};

